example.code:
# templates/nginx.conf.j2
server {
  listen {{ nginx_port }};
  server_name {{ inventory_hostname }};
  {% for upstream in app_servers %}
  upstream {{ upstream.name }} { server {{ upstream.ip }}; }
  {% endfor %}
}
# Task:
- template:
    src: nginx.conf.j2
    dest: /etc/nginx/nginx.conf
    validate: 'nginx -t -c %s'
